/* audio/eq.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function clamp(n, min, max) { return Math.min(max, Math.max(min, n)); }

  function normalizeEqFilter(filter, index) {
    const fallback = P.DEFAULT_EQ_FILTERS[Math.min(index, P.DEFAULT_EQ_FILTERS.length - 1)] || P.DEFAULT_EQ_FILTERS[0];
    const type = ["peaking", "lowshelf", "highshelf", "lowpass", "highpass", "notch"].includes(filter?.type) ? filter.type : fallback.type;
    return {
      id: typeof filter?.id === "string" ? filter.id : `f${Date.now()}_${index}`,
      type,
      freq: P.clamp(Math.round(Number(filter?.freq) || fallback.freq), P.EQ_MIN_FREQ, P.EQ_MAX_FREQ),
      gain: P.clamp(Math.round(Number(filter?.gain) || 0), P.EQ_MIN_GAIN, P.EQ_MAX_GAIN),
      q: P.clamp(Number(filter?.q) || fallback.q, P.EQ_MIN_Q, P.EQ_MAX_Q),
      enabled: filter?.enabled !== false,
    };
  }

  function syncEqNodes() {
    if (!P.eqInputNode || !P.audioContext) return;
    try { P.eqInputNode.disconnect(); } catch {}
    P.eqFilters.forEach((f) => { try { f.node.disconnect(); } catch {} });

    let prev = P.eqInputNode;
    P.eqFilters.forEach((entry) => {
      const cfg = entry.cfg;
      const node = entry.node;
      node.type = cfg.type;
      node.frequency.value = cfg.freq;
      node.Q.value = cfg.q;
      node.gain.value = cfg.type === "lowpass" || cfg.type === "highpass" || cfg.type === "notch" ? 0 : cfg.gain;
      if (P.state.eqEnabled && cfg.enabled) {
        try { prev.connect(node); } catch {}
        prev = node;
      }
    });
    try { prev.connect(P.outputDestination() || P.audioContext.destination); } catch {}
  }

  function ensureEqChain() {
    const main = P.ensureMainGain();
    if (!main) return null;
    if (P.eqFilters.length) return { context: main.context, filters: P.eqFilters };
    try {
      P.ensureLimiter();
      P.eqInputNode = main.context.createGain();
      P.eqInputNode.gain.value = 1;
      P.eqFilters = P.state.eqFilters.map((cfg, index) => {
        const normalized = P.normalizeEqFilter(cfg, index);
        P.state.eqFilters[index] = normalized;
        return { cfg: normalized, node: main.context.createBiquadFilter() };
      });
      P.syncEqNodes();
      P.connectMainOutput();
    } catch {
      P.eqFilters = [];
      P.eqInputNode = null;
    }
    return { context: main.context, filters: P.eqFilters };
  }

  function applyEqState() {
    if (P.state.eqEnabled) P.ensureEqChain();
    if (P.eqInputNode) P.syncEqNodes();
    P.connectMainOutput();
  }

  function setEqEnabled(enabled) {
    P.state.eqEnabled = !!enabled;
    if (P.state.eqEnabled) P.ensureEqChain();
    P.applyEqState();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function setEqParam(index, key, value) {
    const cfg = P.state.eqFilters[index];
    if (!cfg) return;
    if (key === "type") cfg.type = value;
    if (key === "freq") cfg.freq = P.clamp(Math.round(Number(value) || cfg.freq), P.EQ_MIN_FREQ, P.EQ_MAX_FREQ);
    if (key === "gain") cfg.gain = P.clamp(Math.round(Number(value) || 0), P.EQ_MIN_GAIN, P.EQ_MAX_GAIN);
    if (key === "q") cfg.q = P.clamp(Number(value) || cfg.q, P.EQ_MIN_Q, P.EQ_MAX_Q);
    if (key === "enabled") cfg.enabled = !!value;
    P.state.eqFilters[index] = P.normalizeEqFilter(cfg, index);
    if (P.state.eqEnabled) P.ensureEqChain();
    P.applyEqState();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function addEqFilter() {
    const idx = P.state.eqFilters.length;
    const base = P.DEFAULT_EQ_FILTERS[idx % P.DEFAULT_EQ_FILTERS.length] || P.DEFAULT_EQ_FILTERS[1];
    P.state.eqFilters.push(P.normalizeEqFilter({ ...base, id: `f${Date.now()}_${idx}`, freq: base.freq, gain: 0 }, idx));
    if (P.eqFilters.length) { // rebuild chain cleanly
      P.eqFilters.forEach((f) => { try { f.node.disconnect(); } catch {} });
      P.eqFilters = [];
      P.eqInputNode = null;
    }
    if (P.state.eqEnabled) P.ensureEqChain();
    P.applyEqState();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function removeEqFilter(index) {
    if (!P.state.eqFilters[index] || P.state.eqFilters.length <= 1) return;
    P.state.eqFilters.splice(index, 1);
    P.eqFilters.forEach((f) => { try { f.node.disconnect(); } catch {} });
    P.eqFilters = [];
    P.eqInputNode = null;
    if (P.state.eqEnabled) P.ensureEqChain();
    P.applyEqState();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function resetEq() {
    P.state.eqFilters = P.DEFAULT_EQ_FILTERS.map((f) => ({ ...f }));
    P.eqFilters.forEach((f) => { try { f.node.disconnect(); } catch {} });
    P.eqFilters = [];
    P.eqInputNode = null;
    if (P.state.eqEnabled) P.ensureEqChain();
    P.applyEqState();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }
  Object.assign(P, { clamp, normalizeEqFilter, syncEqNodes, ensureEqChain, applyEqState, setEqEnabled, setEqParam, addEqFilter, removeEqFilter, resetEq });
}
